      "type": "string",
      "minLength": 1
    },
    "cost_estimate_timestamp": {
      "type": "string",
      "format": "date-time",
      "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$"
    },
    "isolation_mode": {
      "type": "string",
      "enum": ["fresh-agent", "same-session-file-reload"]
    },
    "fallback_reason": {
      "type": "string"
    },
    "handoff_reload_evidence_hash": {
      "type": "string"
    },
    "allowed_inputs": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["path", "sha256"],
        "properties": {
          "path": {
            "$ref": "#/$defs/repositoryPath"
          },
          "sha256": {
            "$ref": "#/$defs/sha256"
          }
        }
      }
    },
    "allowed_outputs": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/repositoryPath"
      }
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "isolation_mode": {
            "const": "fresh-agent"
          }
        },
        "required": ["isolation_mode"]
      },
      "then": {
        "properties": {
          "fallback_reason": {
            "const": ""
          },
          "handoff_reload_evidence_hash": {
            "const": ""
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "isolation_mode": {
            "const": "same-session-file-reload"
          }
        },
        "required": ["isolation_mode"]
      },
      "then": {
        "properties": {
          "fallback_reason": {
            "type": "string",
            "minLength": 1
          },
          "handoff_reload_evidence_hash": {
            "$ref": "#/$defs/sha256"
          }
        }
      }
    }
  ],
  "$defs": {
    "nonEmptyId": {
      "type": "string",
      "pattern": "^[A-Za-z0-9][A-Za-z0-9._:-]*$"
    },
    "repositoryPath": {
      "type": "string",
      "pattern": "^(?!/)(?!.*//[^/])(?!.*\\\\)(?!.*(^|/)\\.\\.?(/|$))[A-Za-z0-9.][A-Za-z0-9._/-]*$"
    },
    "sha256": {
      "type": "string",
      "pattern": "^[a-f0-9]{64}$"
    }
  }
}
